\label{thm-1-1}
There exist absolute constants $C_1,C_2\ge1$ with the following property. For every $\varepsilon\in(0,1)$ and all integers $d,N\ge2$, there exists an explicitly constructed finite set $W_{d,\varepsilon}(N)\subset\mathbb T^d$ such that
\begin{equation}\label{eq:generalcard-1-4}
 |W_{d,\varepsilon}(N)|
 \le \bigl(C_1(1+\varepsilon^{-1})\bigr)^{d-1}N^{1+\varepsilon}
\end{equation}
and
\begin{equation}\label{eq:generalnorm-1-5}
 \|f\|_\infty
 \le \bigl(C_2(1+\varepsilon^{-1})\bigr)^{d-1}
 \|f\|_{W_{d,\varepsilon}(N)},
 \qquad f\in\mathcal T(N,d).
\end{equation}

\label{thm:main}
Let $d,N\ge2$, $\varepsilon\in(0,1)$, and $\eta\in(0,1)$. There exist constants $C(d,\varepsilon)>0$ and $B_{d,\varepsilon}>0$ with
$
 B_{d,\varepsilon}\le
 \exp\bigl(C_d\varepsilon^{-d}\bigr)$ such that,  whenever
\begin{equation}\label{eq:m-random-intro}
 m\ge C(d,\varepsilon)\log\frac2\eta\,N^{1+\varepsilon},
\end{equation}
the inequality
\begin{equation}\label{eq:random-norming-intro}
 \|f\|_\infty\le
 B_{d,\varepsilon} \|f\|_{X_m}
\end{equation}
holds simultaneously for all $f\in\mathcal T(N,d)$ with probability at least $1-\eta$.

\label{lem:combination}
Let $P_j:C(\mathbb T)\to C(\mathbb T)$, $j=0,1,\ldots$, be a sequence of linear operators, and set
\[
 D_0:=P_0,
 \qquad
 D_j:=P_j-P_{j-1},\quad j\ge1.
\]
Then, for every integer $n\ge d-1$,
\begin{equation}\label{eq:abstractcombination}
 \sum_{|\nu|_1\le n}
 D_{\nu_1}^{(1)}\cdots D_{\nu_d}^{(d)}
 =\sum_{j=0}^{d-1}(-1)^j\binom{d-1}{j}
 \sum_{|\nu|_1=n-j}
 P_{\nu_1}^{(1)}\cdots P_{\nu_d}^{(d)},
\end{equation}
where all sums are taken over $\nu\in\mathbb Z_+^d$.

\label{thm:HC-obstruction}
Let $B>1$, and let $W\subset\mathbb T^d$ be a finite set satisfying
\begin{equation}\label{4-1}
 \lVert f\rVert_\infty\le B\lVert f\rVert_W,
 \qquad f\in\mathcal T(1,d).
\end{equation}
Then
\begin{equation}\label{eq:HC-lower}
 |W|\ge
 \left(\frac{\pi d}{2e\log B}\right)^{d/2}
 =\left(\frac{\pi d}{162e\log B}\right)^{d/2}
 \bigl(\dim\mathcal T(1,d)\bigr)^2.
\end{equation}

\label{thm:remez}
Let $V\subset C(\mathbb T^d)$ be translation invariant. Suppose that a finite set $W\subset\mathbb T^d$ and a constant $B>1$ satisfy
\begin{equation}\label{5-3a}
 \lVert f\rVert_\infty\le B\lVert f\rVert_W,
 \qquad f\in V.
\end{equation}
Then
\begin{equation}\label{5-2}
 \mu_d\bigl(S_f(B)\bigr)\ge\frac1{|W|},
 \qquad f\in V.
\end{equation}

\label{lem:leverage}
Let $K_V$ be the reproducing kernel of $V$ in $L^2(\Omega,\mu)$. Then
\begin{equation}\label{6-10a}
 K_V(x,x)\le Kr,
 \qquad x\in\Omega,
 \qquad\text{and}\qquad
 \dim V\le Kr.
\end{equation}
In particular,
\begin{equation}\label{8-4-Nik}
 \lVert F\rVert_\infty\le\sqrt{Kr}\,\lVert F\rVert_2,
 \qquad F\in V.
\end{equation}

\label{lem:chernoff}
Let $0<\delta\le1/2$, $\eta\in(0,1)$, and set $R:=Kr$. If
\begin{equation}\label{eq:mchernoff}
 m\ge3R\delta^{-2}\log(2R/\eta),
\end{equation}
then, with probability at least $1-\eta$,
\begin{equation}\label{eq:frame}
 (1-\delta)\lVert F\rVert_2^2
 \le\lVert F\rVert_{L^2(\Omega_m)}^2
 \le(1+\delta)\lVert F\rVert_2^2,
 \qquad F\in V.
\end{equation}

\label{lem:amp}
Let $\theta\in(0,1]$, set $\ell:=\lceil3/\theta\rceil$, and assume that the frame event \eqref{eq:frame} occurs with
\[
 0<\delta\le(C_K\sqrt K)^{-1}r^{-\theta/2}.
\]
If $\Lambda:=h_K(\widehat S)$ on $V$, then
\[
 \lVert \Lambda^\ell\rVert_{\infty\to\infty}
 \le r^{(1-\theta\ell)/2}
 \le r^{-1}
 \le\frac12.
\]

\label{lem-7-4}
For every $\boldsymbol{n}\in M_{L+d}$, there exists $\boldsymbol{m}\in S_{L+d}$ such that
$\boldsymbol{n}\preceq\boldsymbol{m}$.

\label{prop:transfer}
For every $f\in\mathcal T(N,d)$, there exists $F\in V$ such that
\[
 \lVert f-F\circ\pi\rVert_{L^\infty(\mathbb T^d)}
 \le(L+1)^d\vartheta_0\lVert f\rVert_\infty,
\]
where
\begin{equation}\label{eq:theta-star}
 \vartheta_0:=\frac{2\pi dA^d}{\ell_0}.
\end{equation}

\label{lem:amplify}
Let $B>1$ and $0<\eta<\eta_0<1$. Then
\begin{equation}\label{8-5}
 m_*(N,d,B,\eta)
 \le\left\lceil\frac{\log(1/\eta)}{\log(1/\eta_0)}\right\rceil
 m_*(N,d,B,\eta_0).
\end{equation}
